#!/usr/bin/env python3
"""Generate packaging/udev/70-3dmouse-linux.rules from the device registry.

Only registry devices get rules (FR-702): no blanket vendor rules, no
world-writable modes. Usage: tools/gen-udev-rules.py [--check]
"""
import sys, tomllib, pathlib

root = pathlib.Path(__file__).resolve().parent.parent
reg = tomllib.loads((root / "crates/sm-registry/data/devices.toml").read_text())
out = root / "packaging/udev/70-3dmouse-linux.rules"

lines = [
    "# 3DMouse Linux – device access rules.",
    "# GENERATED by tools/gen-udev-rules.py from crates/sm-registry/data/devices.toml.",
    "# Do not edit by hand; a test (sm-registry) fails if this file is stale.",
    "#",
    "# * hidraw: TAG+=\"uaccess\" gives the user of the active local seat read/write",
    "#   access (logind ACL). Needed by applications that talk to the device via",
    "#   hidapi themselves (e.g. PrusaSlicer). 3dmoused runs as root and does",
    "#   not depend on it. Remote/inactive users get nothing.",
    "# * input: LIBINPUT_IGNORE_DEVICE keeps the compositor from treating the",
    "#   device as a pointer or joystick so it cannot move the cursor twice.",
    "",
    'ACTION=="remove", GOTO="3dmouse_linux_end"',
    'SUBSYSTEM!="hidraw|input", GOTO="3dmouse_linux_end"',
    "",
]
seen = set()
for d in reg["device"]:
    vid, pid = int(d["vid"], 16) if isinstance(d["vid"], str) else d["vid"], int(d["pid"], 16) if isinstance(d["pid"], str) else d["pid"]
    if (vid, pid) in seen:
        continue
    seen.add((vid, pid))
    bus = "0005" if d.get("transport") == "bluetooth" else "0003"
    k = f'{bus}:{vid:04X}:{pid:04X}.*'
    lines.append(f'# {d["name"]} ({vid:04x}:{pid:04x}, {d.get("transport", "usb")})')
    lines.append(f'SUBSYSTEM=="hidraw", KERNELS=="{k}", TAG+="uaccess", ENV{{THREEDMOUSE_LINUX}}="1"')
    lines.append(f'SUBSYSTEM=="input", KERNELS=="{k}", ENV{{LIBINPUT_IGNORE_DEVICE}}="1", ENV{{THREEDMOUSE_LINUX}}="1"')
lines += ["", 'LABEL="3dmouse_linux_end"', ""]
text = "\n".join(lines)
if "--check" in sys.argv:
    if out.read_text() != text:
        sys.exit(f"{out} is stale; run tools/gen-udev-rules.py")
    print("udev rules up to date")
else:
    out.write_text(text)
    print(f"wrote {out} ({len(seen)} devices)")
